package ua.komirka.data;

import android.content.Context;
import org.junit.*;
import org.junit.runner.RunWith;
import org.robolectric.*;
import org.robolectric.annotation.Config;
import org.json.*;
import java.io.*;
import java.util.*;
import ua.komirka.core.*;
import static ua.komirka.core.Models.*;
import static org.junit.Assert.*;

@RunWith(RobolectricTestRunner.class)
@Config(sdk=35)
public class StoreTest {
    private Store store;private Table table;private Column note,amount,flag;
    @Before public void setUp(){Context context=RuntimeEnvironment.getApplication();context.deleteDatabase("komirka.db");store=new Store(context);table=new Table();table.name="Спостереження";table.idMode=IdMode.INCREMENT;note=new Column("Нотатка",Kind.STRING);amount=new Column("Кількість",Kind.INT);flag=new Column("Перевірено",Kind.BOOL);table.columns.addAll(Arrays.asList(note,amount,flag));store.create(table);}
    @After public void tearDown(){store.close();}
    private Draft draft(String text){Draft d=new Draft();d.tableId=table.id;for(Column c:table.columns)d.answered.add(c.key);d.raw.put(note.key,text);d.raw.put(amount.key,"12");d.raw.put(flag.key,"false");return d;}
    @Test public void draftsSurviveReopeningAndDoNotConsumeIds(){Draft d=draft("Чернетка");d.step=2;store.saveDraft(d);assertEquals(0,store.table(table.id).rowCount);assertEquals(1,store.table(table.id).nextId);store.close();store=new Store(RuntimeEnvironment.getApplication());assertEquals("Чернетка",store.draft(table.id).raw.get(note.key));assertEquals(2,store.draft(table.id).step);Row r=store.commit(table,store.draft(table.id));assertEquals("1",r.externalId);assertNull(store.draft(table.id));assertEquals(2,store.table(table.id).nextId);}
    @Test public void editingIsIsolatedUntilCommitAndKeepsTypedAliases(){Row row=store.commit(table,draft("До"));Draft d=store.editDraft(table,row);d.raw.put(note.key,"Після");d.nulls.add(flag.key);store.saveDraft(d);assertEquals("До",store.row(row.id).values.get(note.key));store.commit(table,d);Row changed=store.row(row.id);assertEquals("Після",changed.values.get(note.key));assertEquals("До",changed.history.get(note.key).get(0).value);assertEquals(false,changed.history.get(flag.key).get(0).value);assertNull(changed.values.get(flag.key));assertEquals("1",changed.externalId);assertEquals(2,store.table(table.id).nextId);}
    @Test public void canRestoreReplaceAndDeleteAliases(){Row r=store.commit(table,draft("A"));Draft d=store.editDraft(table,r);d.raw.put(note.key,"B");r=store.commit(table,d);d=store.editDraft(table,r);d.raw.put(note.key,(String)d.history.get(note.key).get(0).value);d.history.get(note.key).get(0).value="Виправлений alias";r=store.commit(table,d);assertEquals("A",r.values.get(note.key));assertEquals("B",r.history.get(note.key).get(0).value);assertEquals("Виправлений alias",r.history.get(note.key).get(1).value);d=store.editDraft(table,r);d.history.get(note.key).clear();r=store.commit(table,d);assertTrue(r.history.get(note.key).isEmpty());}
    @Test public void unchangedNumericValueDoesNotAppendHistory(){Row r=store.commit(table,draft("A"));Draft d=store.editDraft(table,store.row(r.id));r=store.commit(table,d);assertFalse(r.history.containsKey(amount.key));}
    @Test public void rejectsStaleEditsWithoutOverwritingOrRemovingDraft(){Row r=store.commit(table,draft("A"));Draft first=store.editDraft(table,r),stale=store.editDraft(table,r);first.raw.put(note.key,"B");store.commit(table,first);stale.raw.put(note.key,"C");store.saveDraft(stale);assertThrows(IllegalArgumentException.class,()->store.commit(table,stale));assertEquals("B",store.row(r.id).values.get(note.key));assertNotNull(store.draft(table.id));}
    @Test public void duplicateManualIdRollsBackAndKeepsDraft(){Table manual=new Table();manual.name="Manual";manual.idMode=IdMode.MANUAL;manual.columns.add(note);store.create(manual);Draft first=new Draft();first.tableId=manual.id;first.externalId="ABC";first.answered.add(note.key);first.raw.put(note.key,"first");store.commit(manual,first);Draft duplicate=new Draft();duplicate.tableId=manual.id;duplicate.externalId="ABC";duplicate.answered.add(note.key);duplicate.raw.put(note.key,"second");store.saveDraft(duplicate);assertThrows(IllegalArgumentException.class,()->store.commit(manual,duplicate));assertEquals(1,store.table(manual.id).rowCount);assertNotNull(store.draft(manual.id));}
    @Test public void uuidIsCreatedOnlyAtCommitAndIsStableOnEdit(){Table uuid=new Table();uuid.name="UUID";uuid.idMode=IdMode.AUTO;uuid.columns.add(note);store.create(uuid);Draft d=new Draft();d.tableId=uuid.id;d.answered.add(note.key);d.nulls.add(note.key);store.saveDraft(d);Row r=store.commit(uuid,d);UUID.fromString(r.externalId);String id=r.externalId;r=store.commit(uuid,store.editDraft(uuid,r));assertEquals(id,r.externalId);}
    @Test public void importIsAtomicAndKeepsColumnMappingAfterReorder(){Csv.Document csv=Csv.read("Назва,Вага\nЯблуко,1.25\nГруша,2.5");Table t=new Table();t.name="Імпорт";t.idMode=IdMode.INCREMENT;Column weight=new Column("Вага",Kind.FLOAT);weight.sourceIndex=1;Column title=new Column("Назва",Kind.STRING);title.sourceIndex=0;t.columns.addAll(Arrays.asList(weight,title));store.importCsv(t,csv);assertEquals(2,store.table(t.id).rowCount);assertEquals(3,store.table(t.id).nextId);List<Row> rows=store.rows(t.id,"Яблуко",10,0);assertEquals(1,rows.size());assertEquals(1.25,rows.get(0).values.get(weight.key));}
    @Test public void invalidImportDoesNotLeavePartialTable(){Table t=new Table();t.name="Поганий CSV";t.idMode=IdMode.INCREMENT;Column c=new Column("n",Kind.INT);c.sourceIndex=0;t.columns.add(c);assertThrows(IllegalArgumentException.class,()->store.importCsv(t,Csv.read("n\n1\nnot-a-number")));assertNull(store.table(t.id));assertEquals(0,store.countRows(t.id,""));}
    @Test public void jsonRetainsSchemaOrdinalOrderNullBooleansAndAliases() throws Exception {Column rank=new Column("Рівень",Kind.ORDINAL);rank.options.addAll(Arrays.asList("Низький","Високий"));Table t=new Table();t.name="Типи";t.columns.addAll(Arrays.asList(rank,flag));store.create(t);Draft d=new Draft();d.tableId=t.id;d.answered.add(rank.key);d.answered.add(flag.key);d.raw.put(rank.key,"Високий");d.raw.put(flag.key,"false");Row r=store.commit(t,d);d=store.editDraft(t,r);d.nulls.add(rank.key);store.commit(t,d);StringWriter writer=new StringWriter();store.export(t,writer,true);JSONObject json=new JSONObject(writer.toString());assertEquals("Низький",json.getJSONArray("columns").getJSONObject(0).getJSONArray("categories").getString(0));JSONObject row=json.getJSONArray("rows").getJSONObject(0);assertTrue(row.getJSONObject("values").isNull("Рівень"));assertFalse(row.getJSONObject("values").getBoolean("Перевірено"));assertEquals("Високий",row.getJSONObject("aliases").getJSONArray("Рівень").getJSONObject(0).getString("value"));}
    @Test public void csvExportContainsCurrentValuesOnlyAndRoundTrips() throws Exception {Draft d=draft("Лапки \"\nкома,");d.nulls.add(amount.key);store.commit(table,d);StringWriter writer=new StringWriter();store.export(table,writer,false);Csv.Document csv=Csv.read(writer.toString());assertEquals(Arrays.asList("id","Нотатка","Кількість","Перевірено"),csv.headers);assertEquals(Arrays.asList("1","Лапки \"\nкома,","","false"),csv.rows.get(0));}
    @Test public void ukrainianSearchIsCaseInsensitiveAndWildcardsAreLiteral(){store.commit(table,draft("КИЇВ 100% _ ок"));assertEquals(1,store.countRows(table.id,"київ"));assertEquals(1,store.countRows(table.id,"100%"));assertEquals(0,store.countRows(table.id,"100_"));}
    @Test public void deletingRecordsNeverReusesSequenceNumbersAndClearsTheirDraft(){Row first=store.commit(table,draft("A"));store.saveDraft(store.editDraft(table,first));store.deleteRow(first);assertNull(store.draft(table.id));assertEquals("2",store.commit(table,draft("B")).externalId);}
    @Test public void deletingTableCascadesToRecordsAndDrafts(){store.commit(table,draft("A"));store.saveDraft(draft("B"));store.deleteTable(table.id);assertEquals(0,store.countRows(table.id,""));assertNull(store.draft(table.id));}
    @Test public void importedRowsKeepOriginalOrderOnExport() throws Exception {
        StringBuilder source=new StringBuilder("n\n");for(int i=0;i<200;i++)source.append(i).append('\n');
        Table t=new Table();t.name="Порядок";Column c=new Column("n",Kind.INT);c.sourceIndex=0;t.columns.add(c);store.importCsv(t,Csv.read(source.toString()));
        StringWriter writer=new StringWriter();store.export(t,writer,false);Csv.Document result=Csv.read(writer.toString());for(int i=0;i<200;i++)assertEquals(String.valueOf(i),result.rows.get(i).get(0));
    }
}
